<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {createSupportClient,type SupportScope,type SupportTicket} from '../platform/support';
import {ApiError} from '../platform/api';
import {newId} from '../platform/storage';
const props=defineProps<{familyId?:string}>();
const scope=ref<SupportScope>('trial'),kind=ref<SupportTicket['kind']>('support'),body=ref(''),contact=ref(''),associate=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const status=ref<Awaited<ReturnType<ReturnType<typeof createSupportClient>['status']>>|null>(null),tickets=ref<SupportTicket[]>([]),operators=ref<SupportTicket[]>([]),nextCursor=ref('0'),hasMore=ref(false);
const states:Record<string,string>={submitted:'已提交，等待处理',in_progress:'处理中',resolved:'已处理，请查看回复',rejected:'未受理，请查看原因',withdrawn:'已撤回'};
const operatorCursor=ref('0'),operatorHasMore=ref(false);
const operatorId=ref(''),reply=ref(''),evidence=ref(''),operatorStatus=ref('in_progress'),audit=ref('');
let client=createSupportClient(scope.value),generation=0,disposed=false,requestId=newId(),operatorKey='',operatorRequestId='';
function clearOperatorSelection(){operatorId.value='';reply.value='';evidence.value='';audit.value='';operatorKey='';operatorRequestId='';operatorCursor.value='0';operatorHasMore.value=false;}
watch(()=>JSON.stringify([kind.value,body.value,contact.value,associate.value,props.familyId]),()=>{requestId=newId();});
watch(scope,()=>{generation++;client.stop();client=createSupportClient(scope.value);busy.value=false;status.value=null;tickets.value=[];operators.value=[];clearOperatorSelection();notice.value='';requestId=newId();void refresh();});
onUnmounted(()=>{disposed=true;generation++;client.stop();});
async function run(action:(current:()=>boolean)=>Promise<void>){if(busy.value||disposed)return;const token=++generation,current=()=>!disposed&&token===generation;busy.value=true;error.value='';try{await action(current);}catch(e){if(current()){if(e instanceof ApiError&&[401,403].includes(e.status)){status.value=null;tickets.value=[];operators.value=[];clearOperatorSelection();}error.value=e instanceof Error?e.message:'操作未完成';}}finally{if(current())busy.value=false;}}
function refresh(){return run(async current=>{const available=await client.status();if(!current())return;status.value=available;const result=await client.list();if(!current())return;tickets.value=result.tickets;nextCursor.value=result.nextCursor;hasMore.value=result.hasMore;});}
onMounted(()=>{void refresh();});
async function submit(){if(!body.value.trim()||busy.value||!status.value)return;const captured={requestId,kind:kind.value,message:body.value.trim(),...(contact.value.trim()?{contact:contact.value.trim()}:{}),...(associate.value&&scope.value==='account'&&props.familyId?{familyId:props.familyId}:{})};const token=generation;const result=await uni.showModal({title:kind.value==='privacy_deletion'?'提交在线资料删除申请？':'提交问题反馈？',content:`只发送你在这里填写的问题和联系方式${captured.familyId?'及所选家庭编号':''}，不自动附带沟通记录、照片或观察。删除申请需工作人员核验，不会立即删除资料。`,confirmText:'确认提交'});if(!result.confirm||disposed||token!==generation)return;
 await run(async current=>{const ticket=await client.create(captured);if(!current())return;tickets.value=[ticket,...tickets.value.filter(item=>item.id!==ticket.id)];requestId=newId();body.value='';contact.value='';notice.value='已提交，单据与回复可在下方查看。';});}
async function withdraw(ticket:SupportTicket){const token=generation,choice=await uni.showModal({title:'撤回这份未处理申请？',content:'撤回后不会继续处理，已提交的记录按说明保留。',confirmText:'撤回'});if(choice.confirm&&!disposed&&token===generation)void run(async current=>{const result=await client.withdraw(ticket.id);if(current())tickets.value=tickets.value.map(item=>item.id===result.id?result:item);});}
function more(){void run(async current=>{const result=await client.list(nextCursor.value);if(current()){tickets.value=[...tickets.value,...result.tickets.filter(item=>!tickets.value.some(old=>old.id===item.id))];nextCursor.value=result.nextCursor;hasMore.value=result.hasMore;}});}
function loadOperations(){void run(async current=>{const result=await client.operatorList();if(current()){operators.value=result.tickets;operatorCursor.value=result.nextCursor;operatorHasMore.value=result.hasMore;}});}
function moreOperations(){void run(async current=>{const result=await client.operatorList(operatorCursor.value);if(current()){operators.value=[...operators.value,...result.tickets.filter(item=>!operators.value.some(old=>old.id===item.id))];operatorCursor.value=result.nextCursor;operatorHasMore.value=result.hasMore;}});}
function update(){if(!operatorId.value||!reply.value.trim())return;const payload={status:operatorStatus.value,reply:reply.value.trim(),...(evidence.value.trim()?{deletionEvidence:evidence.value.trim()}:{})},key=JSON.stringify([operatorId.value,payload]);if(key!==operatorKey){operatorKey=key;operatorRequestId=newId();}void run(async current=>{await client.update(operatorId.value,{requestId:operatorRequestId,...payload});if(!current())return;const result=await client.operatorList();if(current()){operators.value=result.tickets;operatorCursor.value=result.nextCursor;operatorHasMore.value=result.hasMore;operatorKey='';operatorRequestId='';notice.value='处理回复已保存并记录审计。';}});}
function inspectAudit(id:string){void run(async current=>{const result=await client.audit(id);if(current())audit.value=JSON.stringify(result,null,2);});}
</script>
<template>
 <view class="support-manager"><text class="section-title">问题反馈与在线资料申请</text><text class="modal-copy">只发送你主动填写的文字。不要在问题中粘贴不必要的姓名、健康信息或沟通内容；本机数据清除在设置中操作。</text><view class="scene-options"><button role="button" tabindex="0" :class="{active:scope==='trial'}" @click="scope='trial'">本机体验凭证</button><button role="button" tabindex="0" :class="{active:scope==='account'}" @click="scope='account'">家庭账户</button></view><text v-if="status" class="modal-copy">当前归属：{{status.actorScope==='trial'?'这台设备的体验凭证':'已登录家庭账户'}}。每日最多 {{status.dailyLimit}} 份；已关闭单据保留 {{status.retentionDays}} 天。删除申请不自动删除家庭资料。</text><text v-if="error" role="alert" class="error-copy">{{error}}</text><text v-if="notice" role="status">{{notice}}</text><view class="scene-options"><button role="button" tabindex="0" :class="{active:kind==='support'}" @click="kind='support'">操作问题</button><button role="button" tabindex="0" :class="{active:kind==='privacy_deletion'}" @click="kind='privacy_deletion'">在线资料删除申请</button></view><textarea v-model="body" maxlength="4000" aria-label="问题或删除申请内容" placeholder="说明遇到的问题，或需要删除的在线资料范围"/><input v-model="contact" maxlength="200" aria-label="反馈联系方式" placeholder="联系方式，选填；也可只在这里查看回复"/><button v-if="scope==='account'&&familyId" role="button" tabindex="0" :aria-pressed="associate" @click="associate=!associate">{{associate?'✓':'○'}} 关联当前选中的家庭</button><button role="button" tabindex="0" class="outline-button" :disabled="busy||!status||!body.trim()" @click="submit">提交所填内容</button><button role="button" tabindex="0" class="text-button" :disabled="busy" @click="refresh">刷新我的单据</button><view v-for="ticket in tickets" :key="ticket.id" class="support-ticket"><text>{{ticket.kind==='privacy_deletion'?'删除申请':'问题反馈'}} · {{states[ticket.status]||ticket.status}}</text><text>{{ticket.message}}</text><text v-if="ticket.reply">处理回复：{{ticket.reply}}</text><text v-if="ticket.deletionEvidence">处理依据：{{ticket.deletionEvidence}}</text><text class="modal-copy">{{new Date(ticket.createdAt).toLocaleString('zh-CN')}}</text><button v-if="ticket.status==='submitted'" role="button" tabindex="0" class="text-button" :disabled="busy" @click="withdraw(ticket)">撤回未处理申请</button></view><button v-if="hasMore" role="button" tabindex="0" :disabled="busy" @click="more">查看更多单据</button>
 <template v-if="status?.canOperate&&scope==='account'"><text class="section-title">支持工作台</text><button role="button" tabindex="0" :disabled="busy" @click="loadOperations">查看支持单据</button><view v-for="ticket in operators" :key="ticket.id" class="support-ticket"><button role="button" tabindex="0" @click="operatorId=ticket.id;reply=ticket.reply||'';evidence=ticket.deletionEvidence||''">{{ticket.kind}} · {{states[ticket.status]||ticket.status}} · {{ticket.message}}</button><button role="button" tabindex="0" @click="inspectAudit(ticket.id)">查看处理审计</button></view><button v-if="operatorHasMore" role="button" tabindex="0" :disabled="busy" @click="moreOperations">查看更多支持单据</button><template v-if="operatorId"><text>正在处理：{{operatorId}}</text><view class="scene-options"><button v-for="item in ['in_progress','resolved','rejected']" :key="item" role="button" tabindex="0" :class="{active:operatorStatus===item}" @click="operatorStatus=item">{{states[item]}}</button></view><textarea v-model="reply" maxlength="4000" aria-label="支持处理回复" placeholder="向提交人说明处理结果"/><textarea v-model="evidence" maxlength="2000" aria-label="删除申请处理依据" placeholder="删除申请办结需填真实处理依据，不能仅凭回复宣称已删除"/><button role="button" tabindex="0" :disabled="busy||!reply.trim()" @click="update">保存回复与审计</button></template><textarea v-if="audit" :value="audit" disabled maxlength="-1" aria-label="支持审计记录"/></template></view>
</template>
<style scoped>.support-manager{display:flex;flex-direction:column;gap:16px;border-top:1px solid #e3e8f0;padding-top:24px}.support-manager textarea{box-sizing:border-box;width:100%;min-height:130px;border:1px solid #d9e3f0;border-radius:8px;padding:12px;font-size:15px}.support-manager input{padding:10px;border:1px solid #d9e3f0;border-radius:8px}.support-ticket{display:flex;flex-direction:column;gap:10px;padding:16px;background:#f5f8fc;border-radius:10px;overflow-wrap:anywhere}.support-manager .scene-options{flex-wrap:wrap}</style>
